PREFIX : <https://w3id.org/rastro/ontology#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT DISTINCT ?name WHERE {
  ?trial a :Trial ;
         :phase ?phase ;
         :condition ?c ;
         :testsDrug ?drug .
  FILTER(?phase IN ("PHASE3", "PHASE2/PHASE3"))
  ?c :within ?breast .
  ?breast rdfs:label "Breast Neoplasms"@en .
  ?drug :name ?name ;
        :hasTarget ?target .
  ?target :gene "ERBB2" .
}
ORDER BY ?name

