PREFIX : <https://w3id.org/rastro/ontology#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?sponsorName WHERE {
  {
    SELECT ?sponsorName (COUNT(DISTINCT ?t) AS ?n) WHERE {
      ?t a :Trial ;
         :status ?st ;
         :sponsor ?s ;
         :condition ?c .
      FILTER(?st IN ("TERMINATED", "WITHDRAWN"))
      ?c :within ?lung .
      ?lung rdfs:label "Lung Neoplasms"@en .
      ?s :industry true ;
         :name ?sponsorName .
    }
    GROUP BY ?sponsorName
    ORDER BY DESC(?n)
    LIMIT 3
  }
}
ORDER BY DESC(?n)

